import csv, json, os, re, sys


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = ''.join(c if c.isalnum() else ' ' for c in str(s).casefold())
    return ' '.join(s.split())


def read_csv(path):
    with open(path, encoding='utf-8-sig', newline='') as f:
        text = f.read()
    lines = text.splitlines(True)
    meta = {}
    i = 0
    while i < len(lines) and (lines[i].strip() == '' or lines[i].lstrip().startswith('#')):
        m = re.match(r'\s*#\s*([^:]+?)\s*:\s*(.*?)\s*$', lines[i])
        if m:
            meta[m.group(1).strip().lower()] = m.group(2)
        i += 1
    rows = list(csv.reader(lines[i:]))
    records = []
    header = None
    for row in rows:
        if not row or all(c.strip() == '' for c in row):
            continue
        if header is None:
            header = [c.strip().lower() for c in row]
            continue
        d = dict(zip(header, row))
        ranks = {}
        for k, v in d.items():
            m = re.fullmatch(r'rank(\d+)', k)
            if m and v is not None and v.strip() != '':
                marks = []
                for part in v.split('|'):
                    p = part.strip()
                    if p == '':
                        continue
                    if p[:3].upper() == 'WI:':
                        marks.append(('w', p[3:]))
                    else:
                        marks.append(('c', p))
                ranks[int(m.group(1))] = marks
        records.append((d.get('ballot', ''), (d.get('contest') or '').strip(), ranks))
    return meta, records


def read_jsonl(path):
    meta = None
    records = []
    with open(path, encoding='utf-8-sig') as f:
        for line in f:
            if not line.strip():
                continue
            o = json.loads(line)
            if meta is None:
                meta = o
                continue
            ranks = {}
            for m in o.get('marks', []):
                r = int(m['rank'])
                lst = ranks.setdefault(r, [])
                if m.get('write_in') is not None:
                    lst.append(('w', m['write_in']))
                elif m.get('candidate') is not None:
                    lst.append(('c', m['candidate']))
            records.append((o.get('ballot', ''), o.get('contest', ''), ranks))
    return meta or {}, records


def load_records(cvr):
    batches = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p):
            continue
        if name.endswith('.csv'):
            meta, recs = read_csv(p)
        elif name.endswith('.jsonl'):
            meta, recs = read_jsonl(p)
        else:
            continue
        meta = {str(k).lower(): v for k, v in meta.items()}
        b = str(meta.get('batch', '')).strip()
        rev = int(str(meta.get('revision', '0')).strip())
        status = str(meta.get('status', '')).strip().lower()
        if b not in batches or rev > batches[b][0]:
            batches[b] = (rev, status, recs)
    out = []
    for rev, status, recs in batches.values():
        if status != 'void':
            out.extend(recs)
    return out


def read_ballot(ranks, contest_info):
    cand, withdrawn, wi_text, max_ranks = contest_info
    entries = []
    seen = set()
    for r in range(1, max_ranks + 1):
        ids = set()
        for kind, v in ranks.get(r, []):
            if kind == 'w':
                t = norm_text(v)
                if t in wi_text:
                    ids.add(wi_text[t])
            else:
                ids.add(norm_id(v))
        if not ids:
            entries.append(('skip', None))
            continue
        ids -= withdrawn
        if not ids:
            entries.append(('pass', None))
            continue
        prior = seen
        seen = seen | ids
        ids -= prior
        if not ids:
            entries.append(('skip', None))
        elif len(ids) == 1:
            entries.append(('choice', next(iter(ids))))
        else:
            entries.append(('over', None))
    return entries


def target(entries, continuing):
    n = len(entries)
    i = 0
    while i < n:
        k, v = entries[i]
        if k == 'choice':
            if v in continuing:
                return v
        elif k == 'over':
            return None
        elif k == 'skip':
            if i + 1 >= n or entries[i + 1][0] == 'skip':
                return None
        i += 1
    return None


def count_contest(contest, recs):
    withdrawn = set()
    cands = {}  # normalized -> output id
    for c in contest.get('candidates', []):
        n = norm_id(c['id'])
        if c.get('status') == 'withdrawn':
            withdrawn.add(n)
        else:
            cands[n] = c['id']
    wi_text = {}
    for w in contest.get('write_ins', []):
        n = norm_id(w['id'])
        cands[n] = w['id']
        for t in [w.get('name', '')] + list(w.get('aliases', [])):
            wi_text[norm_text(t)] = n
    info = (cands, withdrawn, wi_text, int(contest['max_ranks']))
    ballots = [read_ballot(r, info) for r in recs]
    lot = [norm_id(x) for x in contest.get('lot_order', [])]
    continuing = set(cands)
    rounds = []
    history = []
    winner = None
    while True:
        tal = {c: 0 for c in continuing}
        active = 0
        for b in ballots:
            t = target(b, continuing)
            if t is not None:
                tal[t] += 1
                active += 1
        history.append(tal)
        rd = {'round': len(rounds) + 1,
              'tallies': {cands[c]: v for c, v in tal.items()},
              'exhausted': len(ballots) - active, 'eliminated': []}
        rounds.append(rd)
        if active == 0:
            break
        top = max(tal, key=lambda c: tal[c])
        if tal[top] * 2 > active or len(continuing) == 1:
            winner = cands[top]
            break
        zeros = [c for c in tal if tal[c] == 0]
        if zeros:
            elim = zeros
        else:
            tied = [c for c in tal if tal[c] == min(tal.values())]
            for h in reversed(history):
                if len(tied) == 1:
                    break
                m = min(h[c] for c in tied)
                tied = [c for c in tied if h[c] == m]
            if len(tied) > 1:
                tied.sort(key=lambda c: lot.index(c) if c in lot else -1)
                tied = [tied[-1]]
            elim = tied
        rd['eliminated'] = sorted(cands[c] for c in elim)
        continuing -= set(elim)
    return {'contest': contest['id'], 'ballots': len(ballots),
            'winner': winner, 'rounds': rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    recs = load_records(os.path.join(inp, 'cvr'))
    by = {}
    for b, c, r in recs:
        by.setdefault(c, []).append(r)
    res = {'election': el['election'],
           'contests': [count_contest(c, by.get(c['id'], [])) for c in el['contests']]}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
